    def _parse_tensor(value, field_name):
        """Parse a full or Voigt-form tensor from an extxyz header value.

        ASE commonly writes stress in six-component Voigt notation, while
        QUIP/GAP writes virials as nine components.  Both representations are
        unambiguous for the symmetric cell-level tensors used here.
        """
        # Header values are normally whitespace separated, but accepting
        # commas as separators makes this tolerant of equivalent extxyz
        # writers.  Strip a pair of brackets when a writer includes them.
        value = value.strip()
        if len(value) >= 2 and value[0] in "[(" and value[-1] in "])":
            value = value[1:-1]
        try:
            values = np.array(
                [item for item in re.split(r"[\\s,]+", value) if item],
                dtype=np.float64,
            )
        except ValueError as err:
            raise RuntimeError(
                f"{field_name} must contain numeric tensor components: {value!r}"
            ) from err

        if values.size == 9:
            return values.reshape(3, 3)
        if values.size == 6:
            # ASE's Voigt order is xx, yy, zz, yz, xz, xy.
            xx, yy, zz, yz, xz, xy = values
            return np.array(
                [[xx, xy, xz], [xy, yy, yz], [xz, yz, zz]], dtype=np.float64
            )
        raise RuntimeError(
            f"{field_name} must contain 6 (Voigt) or 9 tensor components, "
            f"got {values.size}"
        )

