                continue
            elif prop_key in {"force", "forces"}:
                if kv_dict["datatype"] != "R":
                    raise RuntimeError(
                        "datatype for pos must be 'R' instead of {}".format(
                            kv_dict["datatype"]
                        )
                    )
                force_array = data_array[:, used_colomn : used_colomn + field_length]
                used_colomn += field_length
                continue
            else:
