        info_dict["cells"] = np.array([cell])
        info_dict["coords"] = np.array([coords_array]).astype(np.float64)
        info_dict["energies"] = np.array([field_dict_lower["energy"]]).astype(np.float64)
        if force_array is not None:
            info_dict["forces"] = np.array([force_array]).astype(np.float64)

        # QUIP/GAP's direct virial takes precedence when both labels are
        # present.  ASE stores the physically equivalent intensive tensor as
