        virial_value = field_dict_lower.get("virial")
        if virial_value is None:
            virial_value = field_dict_lower.get("virials")
        if virial_value is not None:
            virials = np.array([QuipGapxyzSystems._parse_tensor(virial_value, "virial")])
        else:
            stress_value = field_dict_lower.get("stress")
            if stress_value is None:
                stress_value = field_dict_lower.get("stresses")
            if stress_value is not None:
                stress = QuipGapxyzSystems._parse_tensor(stress_value, "stress")
                virials = np.array([-abs(np.linalg.det(cell)) * stress])
            else:
                virials = None
        if virials is not None:
            info_dict["virials"] = virials
        info_dict["orig"] = np.zeros(3)
        return info_dict


